// intervals = {start, end}. Greedily keep the earliest finishing activity.
int maxActivities(vector<pair<int,int>>& intervals) {
    sort(intervals.begin(), intervals.end(),
         [](auto& a, auto& b){ return a.second < b.second; });   // by finish
    int count = 0, lastEnd = INT_MIN;
    for (auto& [start, end] : intervals)
        if (start >= lastEnd) { count++; lastEnd = end; }
    return count;
}

def max_activities(intervals):
    intervals.sort(key=lambda x: x[1])     # by finish time
    count, last_end = 0, float('-inf')
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

class Solution {
public:
    int eraseOverlapIntervals(vector<vector<int>>& iv) {
        sort(iv.begin(), iv.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        int end = INT_MIN, removed = 0;
        for (auto& x : iv) {
            if (x[0] >= end) end = x[1];
            else removed++;
        }
        return removed;
    }
};

class Solution:
    def eraseOverlapIntervals(self, iv: list[list[int]]) -> int:
        iv.sort(key=lambda x: x[1])
        end, removed = float('-inf'), 0
        for s, e in iv:
            if s >= end:
                end = e
            else:
                removed += 1
        return removed

class Solution {
public:
    int findMinArrowShots(vector<vector<int>>& points) {
        sort(points.begin(), points.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        int arrows = 1; long long pos = points[0][1];
        for (auto& p : points)
            if (p[0] > pos) { arrows++; pos = p[1]; }
        return arrows;
    }
};

class Solution:
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        points.sort(key=lambda p: p[1])
        arrows, pos = 1, points[0][1]
        for s, e in points:
            if s > pos:
                arrows += 1
                pos = e
        return arrows

class Solution {
public:
    int minMeetingRooms(vector<vector<int>>& meetings) {
        sort(meetings.begin(), meetings.end());
        priority_queue<int, vector<int>, greater<>> pq;
        for (auto& m : meetings) {
            if (!pq.empty() && pq.top() <= m[0]) pq.pop();
            pq.push(m[1]);
        }
        return pq.size();
    }
};

import heapq
class Solution:
    def minMeetingRooms(self, meetings: list[list[int]]) -> int:
        meetings.sort()
        pq = []
        for s, e in meetings:
            if pq and pq[0] <= s:
                heapq.heappop(pq)
            heapq.heappush(pq, e)
        return len(pq)

class Solution {
public:
    int findLongestChain(vector<vector<int>>& pairs) {
        sort(pairs.begin(), pairs.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        int cur = INT_MIN, len = 0;
        for (auto& p : pairs)
            if (p[0] > cur) { cur = p[1]; len++; }
        return len;
    }
};

class Solution:
    def findLongestChain(self, pairs: list[list[int]]) -> int:
        pairs.sort(key=lambda p: p[1])
        cur, length = float('-inf'), 0
        for a, b in pairs:
            if a > cur:
                cur = b
                length += 1
        return length

class Solution {
public:
    int scheduleCourse(vector<vector<int>>& courses) {
        sort(courses.begin(), courses.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        priority_queue<int> pq; int time = 0;
        for (auto& c : courses) {
            time += c[0]; pq.push(c[0]);
            if (time > c[1]) { time -= pq.top(); pq.pop(); }
        }
        return pq.size();
    }
};

import heapq
class Solution:
    def scheduleCourse(self, courses: list[list[int]]) -> int:
        courses.sort(key=lambda c: c[1])
        pq = []
        time = 0
        for dur, end in courses:
            time += dur
            heapq.heappush(pq, -dur)
            if time > end:
                time += heapq.heappop(pq)
        return len(pq)
